const builtInRoleKeys = new Set<RoleKey>(roles.map((role) => role.key));

function isBuiltInRole(role: RoleKey): boolean {
  return builtInRoleKeys.has(role);
}

function normalizeRoleKey(value: string): RoleKey {
  const normalized = value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");

  return (normalized || `role_${Date.now()}`) as RoleKey;
}

function getRoleOptions(config?: AdminConfig) {
  const deletedRoleKeys = new Set(config?.deletedRoleKeys ?? []);
  const customRoles = (config?.customRoles ?? []).filter((role) => role.key && role.label);
  const mergedRoles = [...roles, ...customRoles];
  const seenRoleKeys = new Set<RoleKey>();

  return mergedRoles.filter((role) => {
    if ((deletedRoleKeys.has(role.key) && !isBuiltInRole(role.key)) || seenRoleKeys.has(role.key)) {
      return false;
    }

    seenRoleKeys.add(role.key);
    return true;
  });
}

function getConfigRoleLabel(config: AdminConfig, roleKey: RoleKey): string {
  const role = getRoleOptions(config).find((item) => item.key === roleKey);

  if (role) {
    return role.label;
  }

  return (roleKey ? roleKey.replace(/_/g, " ") : "Deleted role").replace(/\b\w/g, (character) =>
    character.toUpperCase()
  );
}

function getConfiguredWorkflowSteps(config: AdminConfig, workflow: Ticket["workflow"]): Ticket["workflow"] {
  const configuredRoleKeys = new Set(getRoleOptions(config).map((role) => role.key));

  return workflow.filter((step) => configuredRoleKeys.has(step.ownerRole));
}

type RolePersonaAssignment = "primary" | "acting" | "fallback";

interface RolePersonaOption {
  id: string;
  userId?: string;
  role: RoleKey;
  roleLabel: string;
  actionRoles: RoleKey[];
  displayName: string;
  email: string;
  initials: string;
  assignment: RolePersonaAssignment;
  region: string;
  site: string;
  productIds: string[];
  pruNames: string[];
}

function getPersonaInitials(displayName: string): string {
  const parts = displayName
    .trim()
    .split(/\s+/)
    .filter(Boolean);

  if (!parts.length) {
    return "NA";
  }

  if (parts.length === 1) {
    return parts[0].slice(0, 2).toUpperCase();
  }

  return `${parts[0][0] ?? ""}${parts[parts.length - 1][0] ?? ""}`.toUpperCase();
}

function getPersonaRoleKeys(persona: Pick<RolePersonaOption, "role" | "actionRoles">): RoleKey[] {
  return Array.from(new Set([persona.role, ...persona.actionRoles]));
}

function personaHasRole(persona: Pick<RolePersonaOption, "role" | "actionRoles">, role: RoleKey): boolean {
  return getPersonaRoleKeys(persona).includes(role);
}

function createFallbackRolePersona(role: { key: RoleKey; label: string }): RolePersonaOption {
  return {
    id: `${role.key}:role`,
    role: role.key,
    roleLabel: role.label,
    actionRoles: [],
    displayName: role.label,
    email: "",
    initials: getPersonaInitials(role.label),
    assignment: "fallback",
    region: ALL_SCOPE_LABEL,
    site: ALL_SCOPE_LABEL,
    productIds: [ALL_SCOPE_VALUE],
    pruNames: [ALL_SCOPE_VALUE]
  };
}

function buildRolePersonaOptions(config: AdminConfig): RolePersonaOption[] {
  const roleOptions = getRoleOptions(config);
  const roleOptionMap = new Map(roleOptions.map((role) => [role.key, role]));
  const activeUsers = config.users.filter((user) => user.active);
  const coveredRoleKeys = new Set<RoleKey>();
  const userPersonas = activeUsers
    .flatMap((user): RolePersonaOption[] => {
      const primaryRoleOption = roleOptionMap.get(user.primaryRole);

      if (!primaryRoleOption) {
        return [];
      }

      const mappedActionRoles = config.responsibilityMappings
        .filter((mapping) => mapping.active && mapping.userIds.includes(user.id))
        .flatMap((mapping) => getResponsibilityMappingRoles(mapping));
      const actionRoles = getUniqueRoleKeys(
        [...user.actionRoles, ...mappedActionRoles].filter(
          (actionRole) => roleOptionMap.has(actionRole) && actionRole !== user.primaryRole
        )
      );

      coveredRoleKeys.add(user.primaryRole);
      actionRoles.forEach((actionRole) => coveredRoleKeys.add(actionRole));

      return [{
        id: `user:${user.id}`,
        userId: user.id,
        role: user.primaryRole,
        roleLabel: primaryRoleOption.label,
        actionRoles,
        displayName: user.displayName,
        email: user.email,
        initials: getPersonaInitials(user.displayName),
        assignment: "primary",
        region: user.region,
        site: user.site,
        productIds: [...user.productIds],
        pruNames: [...user.pruNames]
      }];
    });
  const fallbackPersonas = roleOptions
    .filter((roleOption) => !coveredRoleKeys.has(roleOption.key))
    .map((roleOption) => createFallbackRolePersona(roleOption));

  return [
    ...userPersonas.sort((left, right) => left.displayName.localeCompare(right.displayName)),
    ...fallbackPersonas
  ];
}

function getSessionRolePersona(
  config: AdminConfig,
  persona: RolePersonaOption,
  actingRoleAccessEnabled: boolean
): RolePersonaOption {
  if (persona.assignment === "fallback" || persona.actionRoles.length === 0) {
    return {
      ...persona,
      actionRoles: []
    };
  }

  if (!actingRoleAccessEnabled) {
    return {
      ...persona,
      actionRoles: [],
      assignment: "primary"
    };
  }

  const [actingRole, ...remainingActingRoles] = persona.actionRoles;

  return {
    ...persona,
    role: actingRole,
    roleLabel: getConfigRoleLabel(config, actingRole),
    actionRoles: remainingActingRoles,
    assignment: "acting"
  };
}

function formatPersonaOptionLabel(persona: RolePersonaOption): string {
  if (persona.assignment === "fallback") {
    return persona.roleLabel;
  }

  return `${persona.displayName} - ${persona.roleLabel}`;
}

function formatPersonaAuditActor(persona: RolePersonaOption): string {
  return `${persona.displayName} (${persona.roleLabel})`;
}

function formatPersonaSecondaryRoles(config: AdminConfig, persona: RolePersonaOption): string {
  const secondaryRoles = persona.actionRoles.map((role) => getConfigRoleLabel(config, role));

  return secondaryRoles.length ? secondaryRoles.join(", ") : "None";
}

