function roleCanAccessNavItem(role: RoleKey, item: NavItem): boolean {
  if (!isBuiltInRole(role)) {
    return item.visibleTo === allRoles;
  }

  return (item.visibleTo as readonly RoleKey[]).includes(role);
}

function canAccessModule(role: RoleKey, moduleKey: ModuleKey): boolean {
  const item = navItems.find((candidate) => candidate.key === moduleKey);

  return item ? roleCanAccessNavItem(role, item) : false;
}

function personaCanAccessNavItem(persona: RolePersonaOption, item: NavItem): boolean {
  return getPersonaRoleKeys(persona).some((role) => roleCanAccessNavItem(role, item));
}

function personaCanAccessModule(persona: RolePersonaOption, moduleKey: ModuleKey): boolean {
  const item = navItems.find((candidate) => candidate.key === moduleKey);

  return item ? personaCanAccessNavItem(persona, item) : false;
}

function getPersonaRoleForModule(persona: RolePersonaOption, moduleKey: ModuleKey): RoleKey | undefined {
  if (canAccessModule(persona.role, moduleKey)) {
    return persona.role;
  }

  return persona.actionRoles.find((actionRole) => canAccessModule(actionRole, moduleKey));
}

function firstAccessibleModuleForPersona(persona: RolePersonaOption): ModuleKey {
  return navItems.find((item) => personaCanAccessNavItem(persona, item))?.key ?? "dashboard";
}

function getPersonaForRole(config: AdminConfig, persona: RolePersonaOption, role: RoleKey): RolePersonaOption {
  if (persona.role === role || !personaHasRole(persona, role)) {
    return persona;
  }

  return {
    ...persona,
    role,
    roleLabel: getConfigRoleLabel(config, role),
    assignment: "acting"
  };
}

function canOperateJira(role?: RoleKey): boolean {
  return role ? canAccessModule(role, "jira") : false;
}

function getProductTicketSource(product?: Pick<ProductConfig, "ticketSource">): ProductTicketSource {
  return product?.ticketSource === "nexus" ? "nexus" : "jira";
}

function productUsesJira(product?: Pick<ProductConfig, "ticketSource">): boolean {
  return getProductTicketSource(product) === "jira";
}

function configUsesJira(config: AdminConfig): boolean {
  return config.products.some((product) => product.active && productUsesJira(product));
}

function getProductTicketSourceLabel(productOrSource?: Pick<ProductConfig, "ticketSource"> | ProductTicketSource): string {
  const source =
    typeof productOrSource === "string" ? productOrSource : getProductTicketSource(productOrSource);

  return source === "jira" ? "Jira" : "Platform";
}

function workflowStepMatchesConfiguredStepId(step: Ticket["workflow"][number], configuredStepId: string): boolean {
  return step.id === configuredStepId || step.id.startsWith(`${configuredStepId}-`);
}

function getDefaultRoleDomain(role: RoleKey): RoleDomain {
  if (role === "admin") {
    return "Admin";
  }

  if (
    role === "developer" ||
    role === "it_reviewer" ||
    role === "security_reviewer" ||
    role === "solution_architect" ||
    role === "software_architect" ||
    role === "release_manager" ||
    role === "service_manager" ||
    role === "scrum_master"
  ) {
    return "IT";
  }

  return "Business";
}

function getConfiguredRoleDomain(config: AdminConfig, role: RoleKey): RoleDomain {
  return config.roleDomains.find((roleDomain) => roleDomain.role === role)?.domain ?? getDefaultRoleDomain(role);
}

function roleCanCreateJira(config: AdminConfig, role: RoleKey): boolean {
  return getConfiguredRoleDomain(config, role) === "IT";
}

function getJiraCreatorStepIds(
  workflow?: Pick<TicketTypeWorkflowConfig, "jiraCreatorStepId" | "jiraCreatorStepIds" | "stepIds">
): string[] {
  if (!workflow) {
    return [];
  }

  const configuredStepIds = Array.isArray(workflow.jiraCreatorStepIds) && workflow.jiraCreatorStepIds.length > 0
    ? workflow.jiraCreatorStepIds
    : workflow.jiraCreatorStepId
      ? [workflow.jiraCreatorStepId]
      : [];
  const routeStepIds = new Set(workflow.stepIds ?? []);

  return Array.from(new Set(configuredStepIds.filter((stepId) => routeStepIds.has(stepId))));
}

function getJiraCreatorRolesForTicket(config: AdminConfig, ticket: Ticket): RoleKey[] {
  const route = getWorkflowRouteForConfig(config, ticket.typeId);
  const configuredCreatorStepIds = getJiraCreatorStepIds(route);

  if (!configuredCreatorStepIds.length) {
    return [];
  }

  const configuredCreatorSteps = getConfiguredWorkflowStepsForRoute(route, config).filter((step) =>
    configuredCreatorStepIds.includes(step.id)
  );
  const configuredCreatorRoles = configuredCreatorSteps
    .map((step) => step.ownerRole)
    .filter((role) => roleCanCreateJira(config, role));

  if (configuredCreatorRoles.length > 0) {
    return Array.from(new Set(configuredCreatorRoles));
  }

  return Array.from(
    new Set(
      ticket.workflow
        .filter((step) => configuredCreatorStepIds.some((stepId) => workflowStepMatchesConfiguredStepId(step, stepId)))
        .map((step) => step.ownerRole)
        .filter((role) => roleCanCreateJira(config, role))
    )
  );
}

function canManageJiraForTicket(config: AdminConfig, persona: RolePersonaOption, ticket: Ticket): boolean {
  if (!ticketUsesJira(config, ticket)) {
    return false;
  }

  const jiraRoles = getPersonaRoleKeys(persona).filter((role) => canOperateJira(role));

  if (!jiraRoles.length) {
    return false;
  }

  if (jiraRoles.includes("admin")) {
    return true;
  }

  if (
    canCreateJiraForTicket(ticket, config) &&
    jiraRoles.some((role) => isJiraReadyToCreateNotificationRole(role) && roleHasTicketAccess(ticket, role, config))
  ) {
    return true;
  }

  const jiraCreatorRoles = getJiraCreatorRolesForTicket(config, ticket);

  return Boolean(
    jiraRoles.some((role) => jiraCreatorRoles.includes(role) && personaCanActOnTicketAsRole(persona, ticket, config, role))
  );
}

function canCommentOnJiraForTicket(config: AdminConfig, persona: RolePersonaOption, ticket: Ticket): boolean {
  if (!ticketUsesJira(config, ticket)) {
    return false;
  }

  if (!getValidJiraIssueKey(ticket.relatedJiraKey)) {
    return false;
  }

  return (
    personaHasRole(persona, "admin") ||
    ticketWasSubmittedByPersona(ticket, persona) ||
    getPersonaRoleKeys(persona).some(
      (role) => personaCanActOnTicketAsRole(persona, ticket, config, role) || roleHasTicketAccess(ticket, role, config)
    )
  );
}

function getTicketSearchText(ticket: Ticket, config: AdminConfig): string {
  return [
    ticket.key,
    ticket.title,
    ticket.product,
    ticket.module,
    ticket.site,
    getConfigTicketTypeLabel(config, ticket.typeId)
  ]
    .join(" ")
    .toLowerCase();
}

function parseStringListRecord(value: string | null): Record<string, string[]> {
  if (!value) {
    return {};
  }

  try {
    const parsed = JSON.parse(value) as unknown;

    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      return {};
    }

    return Object.fromEntries(
      Object.entries(parsed).map(([key, items]) => [
        key,
        Array.isArray(items) ? items.filter((item): item is string => typeof item === "string") : []
      ])
    );
  } catch (error) {
    console.error("Failed to parse local read-state record.", {
      error: getErrorMessage(error)
    });
    return {};
  }
}

function parseStringList(value: string | null): string[] {
  if (!value) {
    return [];
  }

  try {
    const parsed = JSON.parse(value) as unknown;

    return Array.isArray(parsed) ? parsed.filter((item): item is string => typeof item === "string") : [];
  } catch (error) {
    console.error("Failed to parse local string list.", {
      error: getErrorMessage(error)
    });
    return [];
  }
}

function getJiraAttentionId(config: AdminConfig, ticket: Ticket): string | null {
  if (!ticketUsesJira(config, ticket)) {
    return null;
  }

  const followUpStatus = getTicketJiraFollowUpStatus(ticket);
  const needsJiraAttention =
    ticket.jiraDraft.status !== "synced" ||
    (followUpStatus !== "not_created" && followUpStatus !== "done" && followUpStatus !== "rejected");

  if (!needsJiraAttention) {
    return null;
  }

  return [
    "jira",
    ticket.key,
    ticket.relatedJiraKey ?? "",
    ticket.jiraDraft.status,
    ticket.jiraDraft.syncedStatus ?? "",
    followUpStatus,
    ticket.jiraDraft.followUpUpdatedAt ?? ""
  ].join(":");
}

function getJiraAttentionIds(config: AdminConfig, tickets: Ticket[]): string[] {
  return tickets.map((ticket) => getJiraAttentionId(config, ticket)).filter((id): id is string => Boolean(id));
}

function buildHeaderAttentionItems({
  approvalScopeTickets,
  config,
  checkedJiraItemIds,
  selectedPersona,
  tickets,
  visibleNotifications
}: {
  approvalScopeTickets: Ticket[];
  config: AdminConfig;
  checkedJiraItemIds: Set<string>;
  selectedPersona: RolePersonaOption;
  tickets: Ticket[];
  visibleNotifications: NotificationItem[];
}): HeaderAttentionItem[] {
  const canShow = (module: ModuleKey) => personaCanAccessModule(selectedPersona, module);
  const items: HeaderAttentionItem[] = [];
  const unreadNotifications = visibleNotifications.filter((item) => item.unread).length;
  const workflowApprovalCount = getApprovalQueueItems(approvalScopeTickets, config, selectedPersona).filter(
    (item) => item.actionable && item.step.status !== "blocked"
  ).length;
  const globalLpoApprovalCount = getGlobalLpoApprovalAttentionCount(approvalScopeTickets, config, selectedPersona);
  const functionMappingCount = getFunctionMappingAttentionCount(approvalScopeTickets, config, selectedPersona);
  const globalizationCount = globalLpoApprovalCount + functionMappingCount;
  const clarificationAttentionCount = getClarificationAttentionCountForPersona(tickets, selectedPersona);
  const escalationTickets = tickets.filter((ticket) => canAccessEscalationsForTicket(config, selectedPersona, ticket));
  const openEscalations = escalationTickets.flatMap((ticket) => ticket.escalations).filter(
    (escalation) => escalation.status !== "resolved"
  ).length;
  const slaBreaches = tickets.filter((ticket) => ticket.slaState === "breach").length;
  const jiraItems = getJiraAttentionIds(config, tickets).filter((id) => !checkedJiraItemIds.has(id)).length;

  if (unreadNotifications > 0 && canShow("notifications")) {
    items.push({
      id: "notifications",
      module: "notifications",
      title: "Unread notifications",
      meta: "New role-visible pings",
      count: unreadNotifications,
      tone: "info"
    });
  }

  if (workflowApprovalCount > 0 && canShow("approvals")) {
    items.push({
      id: "approvals",
      module: "approvals",
      title: "Approval actions",
      meta: "Workflow gates owned by this role",
      count: workflowApprovalCount,
      tone: "warning"
    });
  }

  if (globalizationCount > 0 && canShow("globalization")) {
    items.push({
      id: "globalization",
      module: "globalization",
      title: "Globalization actions",
      meta: functionMappingCount > 0 ? "Internal mapping and product-owner questions" : "Product-owner questions",
      count: globalizationCount,
      tone: "warning"
    });
  }

  if (clarificationAttentionCount > 0 && canShow("clarifications")) {
    items.push({
      id: "clarifications",
      module: "clarifications",
      title: "Clarification follow-up",
      meta: "Threads waiting for this role",
      count: clarificationAttentionCount,
      tone: "warning"
    });
  }

  if (openEscalations > 0 && canShow("escalations")) {
    items.push({
      id: "escalations",
      module: "escalations",
      title: "Active escalations",
      meta: "Escalation branches need follow-up",
      count: openEscalations,
      tone: "danger"
    });
  }

  if (slaBreaches > 0 && canShow("sla")) {
    items.push({
      id: "sla",
      module: "sla",
      title: "SLA breaches",
      meta: "Operational targets are breached",
      count: slaBreaches,
      tone: "danger"
    });
  }

  if (jiraItems > 0 && canShow("jira")) {
    items.push({
      id: "jira",
      module: "jira",
      title: "Jira follow-up",
      meta: "Drafts, created issues, or active Jira states",
      count: jiraItems,
      tone: "info"
    });
  }

  return items;
}

