function AnalyticsPanel({
  tickets,
  expanded = false,
  config,
  selectedPersona
}: {
  tickets: Ticket[];
  expanded?: boolean;
  config: AdminConfig;
  selectedPersona: RolePersonaOption;
}) {
  const [activeReportTab, setActiveReportTab] = useState<ReportsPanelTab>("analytics");
  const [filters, setFilters] = useState<AnalyticsReportFilters>(() => ({ ...emptyAnalyticsReportFilters }));
  const [reportSnapshot, setReportSnapshot] = useState<AnalyticsReportSnapshot | null>(null);

  useEffect(() => {
    setFilters({ ...emptyAnalyticsReportFilters });
    setReportSnapshot(null);
  }, [selectedPersona.id]);

  const regionOptions = useMemo(
    () =>
      buildReportOptions(
        tickets.map((ticket) => getReportRegionForTicket(config, ticket)),
        "All regions"
      ),
    [config, tickets]
  );
  const siteOptions = useMemo(
    () =>
      buildReportOptions(
        tickets.map((ticket) => ticket.site),
        "All sites"
      ),
    [tickets]
  );
  const productOptions = useMemo(
    () =>
      buildReportOptions(
        tickets.map((ticket) => ticket.product),
        "All products"
      ),
    [tickets]
  );
  const pruOptions = useMemo(
    () =>
      buildReportOptions(
        tickets.map((ticket) => ticket.pru),
        "All PRUs"
      ),
    [tickets]
  );
  const typeOptions = useMemo(() => {
    const configuredTypes = config.requestTypes
      .filter((type) => type.active)
      .map((type) => ({ value: type.id, label: type.label }));
    const configuredTypeIds = new Set(configuredTypes.map((type) => type.value));
    const ticketTypesInUse = new Map<string, string>();

    for (const ticket of tickets) {
      if (!configuredTypeIds.has(ticket.typeId)) {
        ticketTypesInUse.set(ticket.typeId, getReportTicketTypeLabel(config, ticket));
      }
    }

    return [
      { value: REPORT_ALL_VALUE, label: "All types" },
      ...configuredTypes,
      ...Array.from(ticketTypesInUse.entries())
        .sort((left, right) => left[1].localeCompare(right[1]))
        .map(([value, label]) => ({ value, label }))
    ];
  }, [config, tickets]);
  const stateOptions = useMemo(
    () => [
      { value: REPORT_ALL_VALUE, label: "All workflow states" },
      ...ticketStateOptions.map((option) => ({ value: option.value, label: option.label }))
    ],
    []
  );
  const priorityOptions = useMemo(
    () =>
      buildReportOptions(
        [
          ...config.priorities.filter((priority) => priority.active).map((priority) => priority.label),
          ...tickets.map((ticket) => ticket.priority)
        ],
        "All priorities"
      ),
    [config.priorities, tickets]
  );
  const slaStateOptions = useMemo(
    () => [
      { value: REPORT_ALL_VALUE, label: "All SLA states" },
      ...(["healthy", "watch", "breach", "paused"] as const satisfies readonly SlaState[]).map((state) => ({
        value: state,
        label: getSlaLabel(state)
      }))
    ],
    []
  );

  const reportFilters = reportSnapshot?.filters ?? filters;
  const previewTickets = useMemo(
    () => filterAnalyticsReportTickets(tickets, config, filters),
    [config, filters, tickets]
  );
  const reportTickets = useMemo(
    () => filterAnalyticsReportTickets(tickets, config, reportFilters),
    [config, reportFilters, tickets]
  );
  const reportIsStale = reportSnapshot ? !analyticsReportFiltersMatch(reportSnapshot.filters, filters) : false;
  const roleActionableGates = getApprovalQueueItems(reportTickets, config, selectedPersona).filter(
    (item) => item.actionable && item.step.status !== "blocked"
  ).length;
  const bugTickets = reportTickets.filter((ticket) => isBugReportTicket(config, ticket)).length;
  const openTickets = reportTickets.filter((ticket) => ticket.state !== "closed").length;
  const slaBreaches = reportTickets.filter((ticket) => ticket.slaState === "breach").length;
  const hasJiraReportTickets = reportTickets.some((ticket) => ticketUsesJira(config, ticket));
  const typeBuckets = useMemo(
    () => buildReportBuckets(reportTickets, (ticket) => getReportTicketTypeLabel(config, ticket)),
    [config, reportTickets]
  );
  const reportFilterTags = [
    reportFilters.region !== REPORT_ALL_VALUE ? `Region: ${getReportFilterLabel(regionOptions, reportFilters.region)}` : "",
    reportFilters.site !== REPORT_ALL_VALUE ? `Site: ${getReportFilterLabel(siteOptions, reportFilters.site)}` : "",
    reportFilters.product !== REPORT_ALL_VALUE
      ? `Product: ${getReportFilterLabel(productOptions, reportFilters.product)}`
      : "",
    reportFilters.pru !== REPORT_ALL_VALUE ? `PRU: ${getReportFilterLabel(pruOptions, reportFilters.pru)}` : "",
    reportFilters.typeId !== REPORT_ALL_VALUE ? `Type: ${getReportFilterLabel(typeOptions, reportFilters.typeId)}` : "",
    reportFilters.state !== REPORT_ALL_VALUE ? `State: ${getReportFilterLabel(stateOptions, reportFilters.state)}` : "",
    reportFilters.priority !== REPORT_ALL_VALUE
      ? `Priority: ${getReportFilterLabel(priorityOptions, reportFilters.priority)}`
      : "",
    reportFilters.slaState !== REPORT_ALL_VALUE
      ? `SLA: ${getReportFilterLabel(slaStateOptions, reportFilters.slaState)}`
      : ""
  ].filter(Boolean);

  function updateFilter(key: keyof AnalyticsReportFilters, value: string) {
    setFilters((current) => ({ ...current, [key]: value }));
  }

  function createReport() {
    setReportSnapshot({
      filters: { ...filters },
      generatedAt: new Date().toISOString()
    });
  }

  function resetReportFilters() {
    setFilters({ ...emptyAnalyticsReportFilters });
    setReportSnapshot(null);
  }

  useEffect(() => {
    if (activeReportTab === "jiraInsights" && !hasJiraReportTickets) {
      setActiveReportTab("analytics");
    }
  }, [activeReportTab, hasJiraReportTickets]);

  return (
    <section className={`panel analytics-panel ${expanded ? "is-expanded" : ""}`}>
      <PanelHeader
        title="Reporting and analytics"
        description="Filter-driven ticket reporting and Jira delivery insights."
        iconName="report"
      />
      <div className="reports-tab-list" role="tablist" aria-label="Reports views">
        <button
          aria-selected={activeReportTab === "analytics"}
          className={activeReportTab === "analytics" ? "is-active" : ""}
          role="tab"
          type="button"
          onClick={() => setActiveReportTab("analytics")}
        >
          Analytics report
        </button>
        <button
          aria-selected={activeReportTab === "leadTime"}
          className={activeReportTab === "leadTime" ? "is-active" : ""}
          role="tab"
          type="button"
          onClick={() => setActiveReportTab("leadTime")}
        >
          Lead time
        </button>
        {hasJiraReportTickets ? (
          <button
            aria-selected={activeReportTab === "jiraInsights"}
            className={activeReportTab === "jiraInsights" ? "is-active" : ""}
            role="tab"
            type="button"
            onClick={() => setActiveReportTab("jiraInsights")}
          >
            Jira insights
          </button>
        ) : null}
      </div>

      <ReportScopeFilterPanel
        filters={filters}
        onCreateReport={createReport}
        onResetFilters={resetReportFilters}
        onUpdateFilter={updateFilter}
        previewTicketCount={previewTickets.length}
        priorityOptions={priorityOptions}
        productOptions={productOptions}
        pruOptions={pruOptions}
        regionOptions={regionOptions}
        reportFilterTags={reportFilterTags}
        reportIsStale={reportIsStale}
        reportSnapshot={reportSnapshot}
        siteOptions={siteOptions}
        slaStateOptions={slaStateOptions}
        stateOptions={stateOptions}
        typeOptions={typeOptions}
      />

      {activeReportTab === "analytics" ? (
        <div className="reports-tab-panel" role="tabpanel">
          <div className="report-summary-grid">
            <ReportSummaryMetric label="Tickets" value={reportTickets.length} />
            <ReportSummaryMetric label="Bugs" value={bugTickets} />
            <ReportSummaryMetric label="Open" value={openTickets} />
            <ReportSummaryMetric label="Approval gates" value={roleActionableGates} />
            <ReportSummaryMetric label="SLA breaches" value={slaBreaches} />
          </div>

          {reportTickets.length === 0 ? (
            <EmptyState title="No report data" body="No visible tickets match the selected filters." />
          ) : (
            <div className="report-visual-stack">
              <div className="report-visual-grid">
                <ReportBarChart
                  title="Tickets by region"
                  buckets={buildReportBuckets(reportTickets, (ticket) => getReportRegionForTicket(config, ticket))}
                />
                <ReportBarChart
                  title="Tickets by site"
                  buckets={buildReportBuckets(reportTickets, (ticket) => getReportValue(ticket.site, "Unassigned site"))}
                />
                <ReportPieChart title="Ticket type mix" buckets={typeBuckets} />
              </div>
              <div className="report-visual-grid">
                <ReportBarChart
                  title="Tickets by product"
                  buckets={buildReportBuckets(reportTickets, (ticket) => getReportValue(ticket.product, "Unassigned product"))}
                />
                <ReportBarChart
                  title="Tickets by PRU"
                  buckets={buildReportBuckets(reportTickets, (ticket) => getReportValue(ticket.pru, "Unassigned PRU"))}
                />
                <ReportBarChart
                  title="Tickets by workflow state"
                  buckets={buildReportBuckets(reportTickets, (ticket) => getTicketStateLabel(ticket.state))}
                />
              </div>
            </div>
          )}
        </div>
      ) : null}

      {activeReportTab === "leadTime" ? (
        <LeadTimeReport config={config} tickets={reportTickets} />
      ) : null}

      {activeReportTab === "jiraInsights" && hasJiraReportTickets ? (
        <JiraInsightsReport config={config} tickets={reportTickets} />
      ) : null}
    </section>
  );
}

function getTicketCreatedAtMs(ticket: Ticket): number {
  const createdAudit = ticket.audit.find((entry) => entry.eventType.toLowerCase().includes("created"));
  const firstAuditMs = Math.min(
    ...ticket.audit
      .map((entry) => parseTicketTimestamp(entry.createdAt))
      .filter((timestamp) => timestamp > 0)
  );
  const firstCommentMs = Math.min(
    ...ticket.comments
      .map((comment) => parseTicketTimestamp(comment.createdAt))
      .filter((timestamp) => timestamp > 0)
  );
  const createdAuditMs = createdAudit ? parseTicketTimestamp(createdAudit.createdAt) : 0;
  const updatedAtMs = parseTicketTimestamp(ticket.updatedAt);
  const candidates = [createdAuditMs, firstAuditMs, firstCommentMs, updatedAtMs].filter((timestamp) => Number.isFinite(timestamp) && timestamp > 0);

  return candidates.length ? Math.min(...candidates) : Date.now();
}

function getTicketResolvedAtMs(ticket: Ticket): number {
  const followUpStatus = getTicketJiraFollowUpStatus(ticket);

  if (ticket.state !== "closed" && followUpStatus !== "done" && followUpStatus !== "rejected") {
    return 0;
  }

  return parseTicketTimestamp(ticket.jiraDraft.followUpUpdatedAt ?? "") || parseTicketTimestamp(ticket.updatedAt);
}

function isTicketResolvedForInsights(ticket: Ticket): boolean {
  return getTicketResolvedAtMs(ticket) > 0;
}

function isTicketOpenForInsights(ticket: Ticket): boolean {
  return !isTicketResolvedForInsights(ticket);
}

function getTicketFirstResponseHours(ticket: Ticket): number | null {
  const createdAtMs = getTicketCreatedAtMs(ticket);
  const firstResponseMs = ticket.comments
    .map((comment) => parseTicketTimestamp(comment.createdAt))
    .filter((timestamp) => timestamp > createdAtMs)
    .sort((left, right) => left - right)[0];

  if (!firstResponseMs) {
    return null;
  }

  return (firstResponseMs - createdAtMs) / 3600000;
}

function averageJiraInsightHours(values: Array<number | null | undefined>): number {
  const numericValues = values.filter((value): value is number => typeof value === "number" && Number.isFinite(value) && value >= 0);

  if (!numericValues.length) {
    return 0;
  }

  return numericValues.reduce((sum, value) => sum + value, 0) / numericValues.length;
}

function formatJiraInsightDuration(hours: number): string {
  if (!Number.isFinite(hours) || hours <= 0) {
    return "0 hrs";
  }

  if (hours >= 24) {
    const days = hours / 24;

    return `${days >= 10 ? Math.round(days) : days.toFixed(1)} days`;
  }

  return `${hours >= 10 ? Math.round(hours) : hours.toFixed(1)} hrs`;
}

function getLeadTimeStatusFromStoredValue(value?: string): string {
  const trimmedValue = value?.trim() ?? "";

  if (!trimmedValue) {
    return "";
  }

  const ticketStateOption = ticketStateOptions.find((option) => option.value === trimmedValue);

  if (ticketStateOption) {
    return ticketStateOption.label;
  }

  const jiraStatusOption = jiraPortalStatusTimelineOptions.find((option) => option.value === trimmedValue);

  if (jiraStatusOption) {
    if (jiraStatusOption.value === "done" || jiraStatusOption.value === "rejected") {
      return "Close";
    }

    return jiraStatusOption.label;
  }

  return trimmedValue.replace(/[_-]+/g, " ");
}

function getWorkflowStepLeadTimeStatus(value?: string): string {
  const trimmedValue = value?.trim() ?? "";

  if (!trimmedValue) {
    return "";
  }

  const [stepLabel] = trimmedValue.split(":");

  return getLeadTimeStatusFromStoredValue(stepLabel);
}

function getTicketLifecycleLeadTimeStatus(ticket: Ticket): string {
  const lifecycleSteps = getTicketLifecycleSteps(ticket);
  const activeStep =
    lifecycleSteps.find((step) => step.state === "active" || step.state === "blocked" || step.state === "rejected") ??
    lifecycleSteps.find((step) => step.state === "waiting") ??
    lifecycleSteps[lifecycleSteps.length - 1];

  return activeStep?.label ?? getTicketCurrentStatusLabel(ticket);
}

function extractLeadTimeAuditStatusChange(
  entry: Ticket["audit"][number]
): { oldStatus?: string; newStatus: string } | null {
  const eventType = entry.eventType.toLowerCase();

  if (eventType.includes("jira follow-up")) {
    const newStatus = getLeadTimeStatusFromStoredValue(entry.newValue);

    return newStatus ? { oldStatus: getLeadTimeStatusFromStoredValue(entry.oldValue), newStatus } : null;
  }

  if (eventType === "workflow status changed") {
    const newStatus = getWorkflowStepLeadTimeStatus(entry.newValue);

    return newStatus ? { oldStatus: getWorkflowStepLeadTimeStatus(entry.oldValue), newStatus } : null;
  }

  if (eventType === "approval clarification requested") {
    return {
      oldStatus: "Review",
      newStatus: "Clarification"
    };
  }

  if (eventType === "approval granted" || eventType === "deviation approval granted") {
    return {
      oldStatus: "New request",
      newStatus: "Review"
    };
  }

  if (eventType === "approval rejected") {
    return {
      oldStatus: "Review",
      newStatus: "Close"
    };
  }

  if (eventType === "jira created") {
    return {
      oldStatus: "Jira draft",
      newStatus: "Planning"
    };
  }

  if (eventType === "ticket reopened") {
    const newStatus = getLeadTimeStatusFromStoredValue(entry.newValue);

    return newStatus ? { oldStatus: getLeadTimeStatusFromStoredValue(entry.oldValue), newStatus } : null;
  }

  return null;
}

function getTicketCurrentLeadTimeStatus(ticket: Ticket): string {
  if (ticket.state === "clarification") {
    return "Review";
  }

  return getTicketLifecycleLeadTimeStatus(ticket);
}

function getTicketInitialLeadTimeStatus(ticket: Ticket, firstEvent?: LeadTimeStatusEvent): string {
  if (firstEvent?.oldStatus) {
    return firstEvent.oldStatus;
  }

  return "New request";
}

function buildTicketLeadTimeStatusEvents(ticket: Ticket, endMs: number): LeadTimeStatusEvent[] {
  const createdAtMs = getTicketCreatedAtMs(ticket);
  const auditEvents = ticket.audit
    .flatMap((entry) => {
      const atMs = parseTicketTimestamp(entry.createdAt);
      const change = extractLeadTimeAuditStatusChange(entry);

      if (!atMs || !change) {
        return [];
      }

      return [
        {
          status: change.newStatus,
          atMs: Math.max(createdAtMs, atMs),
          source: entry.eventType,
          oldStatus: change.oldStatus
        }
      ];
    })
    .sort((left, right) => left.atMs - right.atMs);
  const initialStatus = getTicketInitialLeadTimeStatus(ticket, auditEvents[0]);
  const events: LeadTimeStatusEvent[] = [
    {
      status: initialStatus,
      atMs: createdAtMs,
      source: "Ticket created"
    }
  ];

  for (const event of auditEvents) {
    if (event.atMs > endMs) {
      continue;
    }

    const previous = events[events.length - 1];

    if (previous && previous.atMs === event.atMs && normalizeLeadTimeLabel(previous.status) === normalizeLeadTimeLabel(event.status)) {
      continue;
    }

    if (previous && normalizeLeadTimeLabel(previous.status) === normalizeLeadTimeLabel(event.status)) {
      continue;
    }

    events.push(event);
  }

  const currentStatus = getTicketCurrentLeadTimeStatus(ticket);
  const currentStatusAtMs =
    parseTicketTimestamp(ticket.jiraDraft.followUpUpdatedAt ?? "") ||
    parseTicketTimestamp(ticket.updatedAt) ||
    endMs;
  const lastEvent = events[events.length - 1];

  if (
    currentStatus &&
    lastEvent &&
    currentStatusAtMs <= endMs &&
    currentStatusAtMs > lastEvent.atMs &&
    normalizeLeadTimeLabel(currentStatus) !== normalizeLeadTimeLabel(lastEvent.status)
  ) {
    events.push({
      status: currentStatus,
      atMs: currentStatusAtMs,
      source: "Current ticket status"
    });
  }

  return events.sort((left, right) => left.atMs - right.atMs);
}

function leadTimeStatusMatchesRule(status: string, ruleStatus: string): boolean {
  const normalizedStatus = normalizeLeadTimeLabel(status);
  const normalizedRuleStatus = normalizeLeadTimeLabel(ruleStatus);

  if (!normalizedStatus || !normalizedRuleStatus) {
    return false;
  }

  return (
    normalizedStatus === normalizedRuleStatus ||
    (normalizedRuleStatus.length >= 4 && normalizedStatus.includes(normalizedRuleStatus))
  );
}

function getDefaultLeadTimeOwnershipForStatus(status: string): LeadTimeOwnership | undefined {
  switch (normalizeLeadTimeLabel(status)) {
    case "new request":
    case "close":
    case "done":
    case "planned release":
      return "process";
    case "review":
      return "mixed";
    case "planning":
    case "in progress":
    case "in project":
    case "it test":
      return "it";
    case "business test":
    case "clarification":
    case "waiting for clarification":
      return "business";
    default:
      return undefined;
  }
}

function getLeadTimeSegmentClassification(
  config: AdminConfig,
  fromStatus: string,
  toStatus: string
): { ownership: LeadTimeOwnershipBucket; ruleKind: LeadTimeRuleKind; ruleLabel: string } {
  const transitionRule = config.leadTimeTransitionRules.find(
    (rule) =>
      rule.active &&
      normalizeLeadTimeLabel(rule.fromStatus) === normalizeLeadTimeLabel(fromStatus) &&
      normalizeLeadTimeLabel(rule.toStatus) === normalizeLeadTimeLabel(toStatus)
  );

  if (transitionRule) {
    return {
      ownership: transitionRule.ownership,
      ruleKind: "transition",
      ruleLabel: `${transitionRule.fromStatus} -> ${transitionRule.toStatus}`
    };
  }

  const statusRule = config.leadTimeStatusRules.find(
    (rule) => rule.active && leadTimeStatusMatchesRule(fromStatus, rule.status)
  );

  if (statusRule) {
    return {
      ownership: statusRule.ownership,
      ruleKind: "status",
      ruleLabel: statusRule.status
    };
  }

  const defaultOwnership = getDefaultLeadTimeOwnershipForStatus(fromStatus);

  if (defaultOwnership) {
    return {
      ownership: defaultOwnership,
      ruleKind: "status",
      ruleLabel: `Default lifecycle: ${fromStatus}`
    };
  }

  return {
    ownership: "unclassified",
    ruleKind: "none",
    ruleLabel: "No matching rule"
  };
}

function buildTicketLeadTimeMetrics(ticket: Ticket, config: AdminConfig, nowMs: number): TicketLeadTimeMetrics {
  const startedAtMs = getTicketCreatedAtMs(ticket);
  const resolvedAtMs = getTicketResolvedAtMs(ticket);
  const endedAtMs = resolvedAtMs || nowMs;
  const events = buildTicketLeadTimeStatusEvents(ticket, endedAtMs);
  const segments = events.flatMap((event, index): LeadTimeSegment[] => {
    const nextEvent = events[index + 1];
    const segmentEndMs = nextEvent?.atMs ?? endedAtMs;

    if (segmentEndMs <= event.atMs) {
      return [];
    }

    const toStatus = nextEvent?.status ?? getTicketCurrentLeadTimeStatus(ticket);
    const classification = getLeadTimeSegmentClassification(config, event.status, toStatus);
    const hours = (segmentEndMs - event.atMs) / 3600000;

    return [
      {
        fromStatus: event.status,
        toStatus,
        startMs: event.atMs,
        endMs: segmentEndMs,
        hours,
        ownership: classification.ownership,
        ruleKind: classification.ruleKind,
        ruleLabel: classification.ruleLabel
      }
    ];
  });
  const totals = segments.reduce(
    (summary, segment) => {
      if (segment.ownership === "business") {
        summary.businessHours += segment.hours;
        summary.processHours += segment.hours;
      } else if (segment.ownership === "it") {
        summary.itHours += segment.hours;
        summary.processHours += segment.hours;
      } else if (segment.ownership === "mixed") {
        summary.businessHours += segment.hours / 2;
        summary.itHours += segment.hours / 2;
        summary.mixedHours += segment.hours;
        summary.processHours += segment.hours;
      } else if (segment.ownership === "process") {
        summary.processHours += segment.hours;
      } else {
        summary.unclassifiedHours += segment.hours;
      }

      return summary;
    },
    {
      businessHours: 0,
      itHours: 0,
      mixedHours: 0,
      processHours: 0,
      unclassifiedHours: 0
    }
  );
  const totalHours = Math.max(0, (endedAtMs - startedAtMs) / 3600000);

  return {
    ticket,
    currentStatus: getTicketCurrentLeadTimeStatus(ticket),
    startedAtMs,
    endedAtMs,
    isOpen: !resolvedAtMs,
    totalHours,
    businessHours: totals.businessHours,
    itHours: totals.itHours,
    processHours: totals.processHours,
    unclassifiedHours: totals.unclassifiedHours,
    mixedHours: totals.mixedHours,
    segments
  };
}

function averageLeadTimeHours(metrics: TicketLeadTimeMetrics[], getValue: (metric: TicketLeadTimeMetrics) => number): number {
  if (!metrics.length) {
    return 0;
  }

  return metrics.reduce((sum, metric) => sum + getValue(metric), 0) / metrics.length;
}

function LeadTimeReport({ config, tickets }: { config: AdminConfig; tickets: Ticket[] }) {
  const latestTicketActivityMs = useMemo(() => {
    const timestamps = tickets
      .map((ticket) => parseTicketTimestamp(ticket.updatedAt))
      .filter((timestamp) => timestamp > 0);

    return timestamps.length ? Math.max(...timestamps) : 0;
  }, [tickets]);
  const [reportGeneratedAtMs, setReportGeneratedAtMs] = useState<number | null>(null);

  useEffect(() => {
    setReportGeneratedAtMs(Date.now());
  }, [config.leadTimeStatusRules, config.leadTimeTransitionRules, tickets]);

  const metrics = useMemo(() => {
    const nowMs = reportGeneratedAtMs ?? latestTicketActivityMs;

    return tickets.map((ticket) => buildTicketLeadTimeMetrics(ticket, config, nowMs));
  }, [config, latestTicketActivityMs, reportGeneratedAtMs, tickets]);
  const openTickets = metrics.filter((metric) => metric.isOpen).length;
  const resolvedTickets = metrics.length - openTickets;
  const avgTotalHours = averageLeadTimeHours(metrics, (metric) => metric.totalHours);
  const avgBusinessHours = averageLeadTimeHours(metrics, (metric) => metric.businessHours);
  const avgItHours = averageLeadTimeHours(metrics, (metric) => metric.itHours);
  const avgProcessHours = averageLeadTimeHours(metrics, (metric) => metric.processHours);
  const totalUnclassifiedHours = metrics.reduce((sum, metric) => sum + metric.unclassifiedHours, 0);
  const totalLeadTimeHours = metrics.reduce((sum, metric) => sum + metric.totalHours, 0);
  const unclassifiedPercentage = totalLeadTimeHours ? Math.round((totalUnclassifiedHours / totalLeadTimeHours) * 100) : 0;
  const ticketRows = [...metrics]
    .sort((left, right) => right.totalHours - left.totalHours)
    .slice(0, 12)
    .map((metric) => [
      `${metric.ticket.key} - ${metric.ticket.title}`,
      metric.currentStatus,
      formatJiraInsightDuration(metric.totalHours),
      formatJiraInsightDuration(metric.businessHours),
      formatJiraInsightDuration(metric.itHours),
      formatJiraInsightDuration(metric.processHours),
      formatJiraInsightDuration(metric.unclassifiedHours),
      metric.isOpen ? "Open" : "Resolved"
    ]);
  const segmentRows = metrics
    .flatMap((metric) =>
      metric.segments.map((segment) => ({
        ticketKey: metric.ticket.key,
        segment
      }))
    )
    .sort((left, right) => right.segment.endMs - left.segment.endMs)
    .slice(0, 12)
    .map((row) => [
      row.ticketKey,
      `${row.segment.fromStatus} -> ${row.segment.toStatus}`,
      getLeadTimeOwnershipLabel(row.segment.ownership),
      formatJiraInsightDuration(row.segment.hours),
      row.segment.ruleKind === "none" ? "Unmatched" : row.segment.ruleLabel,
      formatDateTimeDisplay(new Date(row.segment.endMs).toISOString())
    ]);
  const ownershipBuckets: ReportBucket[] = [
    {
      label: "Business",
      value: Math.round(metrics.reduce((sum, metric) => sum + metric.businessHours, 0)),
      percentage: 0,
      color: "#15803d"
    },
    {
      label: "IT",
      value: Math.round(metrics.reduce((sum, metric) => sum + metric.itHours, 0)),
      percentage: 0,
      color: "#1d4ed8"
    },
    {
      label: "Process only",
      value: Math.round(metrics.reduce((sum, metric) => sum + metric.processHours - metric.businessHours - metric.itHours, 0)),
      percentage: 0,
      color: "#7c5f17"
    },
    {
      label: "Unclassified",
      value: Math.round(totalUnclassifiedHours),
      percentage: 0,
      color: "#dc2626"
    }
  ];
  const ownershipTotal = ownershipBuckets.reduce((sum, bucket) => sum + bucket.value, 0);
  const normalizedOwnershipBuckets = ownershipBuckets.map((bucket) => ({
    ...bucket,
    value: Math.max(0, bucket.value),
    percentage: ownershipTotal ? (Math.max(0, bucket.value) / ownershipTotal) * 100 : 0
  }));

  return (
    <div className="jira-insights-report lead-time-report reports-tab-panel" role="tabpanel">
      <div className="jira-insights-header">
        <div>
          <h3>Lead time report</h3>
          <p>
            Business, IT, process, and total lead time calculated from ticket audit/status history using the configured
            lead-time rules.
          </p>
        </div>
        <span>{formatCount(config.leadTimeTransitionRules.filter((rule) => rule.active).length)} transition rules</span>
      </div>

      {metrics.length === 0 ? (
        <EmptyState title="No lead-time data" body="No visible tickets match the current report filters." />
      ) : (
        <>
          <div className="jira-insight-kpi-grid">
            <JiraInsightKpiCard label="Tickets" value={metrics.length} trend={`${formatCount(openTickets)} open / ${formatCount(resolvedTickets)} resolved`} />
            <JiraInsightKpiCard label="Avg total lead time" value={formatJiraInsightDuration(avgTotalHours)} trend="created to resolved or now" tone="warning" />
            <JiraInsightKpiCard label="Avg Business lead time" value={formatJiraInsightDuration(avgBusinessHours)} trend="business-owned segments" tone="success" />
            <JiraInsightKpiCard label="Avg IT lead time" value={formatJiraInsightDuration(avgItHours)} trend="IT-owned segments" />
            <JiraInsightKpiCard label="Avg process lead time" value={formatJiraInsightDuration(avgProcessHours)} trend={`${unclassifiedPercentage}% unclassified`} tone={unclassifiedPercentage ? "danger" : "success"} />
          </div>
          <div className="jira-insight-split-grid">
            <JiraInsightBarList title="Lead time by owner" buckets={normalizedOwnershipBuckets} />
            <JiraInsightQuickList
              items={[
                {
                  title: `${formatCount(config.leadTimeTransitionRules.filter((rule) => rule.active).length)} active transition rules`,
                  detail: "Exact from/to status rules are evaluated before status fallback rules.",
                  tone: "success"
                },
                {
                  title: `${formatCount(config.leadTimeStatusRules.filter((rule) => rule.active).length)} active status rules`,
                  detail: "Fallback rules classify segments by the starting status.",
                  tone: "success"
                },
                {
                  title: `${formatJiraInsightDuration(totalUnclassifiedHours)} unclassified`,
                  detail: "Add rules for unmatched statuses to improve process lead-time coverage.",
                  tone: unclassifiedPercentage ? "warning" : "success"
                }
              ]}
            />
            <JiraInsightTable
              title="Ticket lead time"
              columns={["Ticket", "Current status", "Total", "Business", "IT", "Process", "Unclassified", "State"]}
              rows={ticketRows}
            />
            <JiraInsightTable
              title="Recent classified segments"
              columns={["Ticket", "Segment", "Owner", "Duration", "Rule", "Until"]}
              rows={segmentRows}
            />
          </div>
        </>
      )}
    </div>
  );
}

function getJiraInsightStatusLabel(ticket: Ticket): string {
  const followUpStatus = getTicketJiraFollowUpStatus(ticket);

  if (ticket.audit.some((entry) => entry.eventType.toLowerCase().includes("reopen"))) {
    return "Reopened";
  }

  if (followUpStatus === "done" || ticket.state === "closed") {
    return "Resolved";
  }

  if (followUpStatus === "in_progress" || followUpStatus === "it_test" || followUpStatus === "business_test") {
    return "In Progress";
  }

  if (followUpStatus === "blocked" || ticket.state === "escalated") {
    return "Blocked";
  }

  return "Open";
}

function buildJiraInsightBuckets(
  tickets: Ticket[],
  getLabel: (ticket: Ticket) => string,
  colors = reportChartColors
): ReportBucket[] {
  return buildReportBuckets(tickets, getLabel).map((bucket, index) => ({
    ...bucket,
    color: colors[index % colors.length]
  }));
}

function buildJiraInsightTrendSeries(tickets: Ticket[], days = 30) {
  const bucketCount = 7;
  const now = new Date();
  const endMs = now.getTime();
  const startMs = endMs - days * 24 * 60 * 60 * 1000;
  const bucketMs = (endMs - startMs) / bucketCount;
  const formatter = new Intl.DateTimeFormat("en-US", { month: "short", day: "2-digit" });

  return Array.from({ length: bucketCount }, (_, index) => {
    const bucketStart = startMs + index * bucketMs;
    const bucketEnd = index === bucketCount - 1 ? endMs + 1 : bucketStart + bucketMs;
    const created = tickets.filter((ticket) => {
      const createdAtMs = getTicketCreatedAtMs(ticket);

      return createdAtMs >= bucketStart && createdAtMs < bucketEnd;
    }).length;
    const resolved = tickets.filter((ticket) => {
      const resolvedAtMs = getTicketResolvedAtMs(ticket);

      return resolvedAtMs >= bucketStart && resolvedAtMs < bucketEnd;
    }).length;

    return {
      label: formatter.format(new Date(bucketStart)),
      created,
      resolved
    };
  });
}

function getJiraInsightResolutionHours(ticket: Ticket): number | null {
  const resolvedAtMs = getTicketResolvedAtMs(ticket);

  if (!resolvedAtMs) {
    return null;
  }

  return Math.max(0, (resolvedAtMs - getTicketCreatedAtMs(ticket)) / 3600000);
}

function getJiraInsightTrendValue(current: number, previous: number): string {
  if (!previous && current) {
    return "new";
  }

  if (!previous) {
    return "0%";
  }

  const delta = ((current - previous) / previous) * 100;

  return `${delta >= 0 ? "+" : ""}${Math.round(delta)}%`;
}

function getJiraInsightWindowTickets(tickets: Ticket[], days: number, previous = false): Ticket[] {
  const nowMs = Date.now();
  const windowMs = days * 24 * 60 * 60 * 1000;
  const endMs = previous ? nowMs - windowMs : nowMs;
  const startMs = endMs - windowMs;

  return tickets.filter((ticket) => {
    const createdAtMs = getTicketCreatedAtMs(ticket);
    const updatedAtMs = parseTicketTimestamp(ticket.updatedAt);
    const activityMs = Math.max(createdAtMs, updatedAtMs);

    return activityMs >= startMs && activityMs < endMs;
  });
}

function getJiraInsightHighPriorityTickets(tickets: Ticket[]): Ticket[] {
  return tickets.filter((ticket) => {
    const priority = ticket.priority.toLowerCase();

    return priority.includes("critical") || priority.includes("high") || priority.startsWith("1") || priority.startsWith("2");
  });
}

function getJiraInsightReleaseRows(tickets: Ticket[]) {
  return buildJiraInsightBuckets(tickets, getReleasePlanVersion, ["#3b82f6", "#60a5fa", "#22c55e", "#f59e0b", "#ef4444"])
    .filter((bucket) => bucket.label !== releasePlanUnplannedLabel)
    .slice(0, 8);
}

function JiraInsightsReport({ config, tickets: reportTickets }: { config: AdminConfig; tickets: Ticket[] }) {
  const [activeView, setActiveView] = useState<JiraInsightsView>("overview");
  const tickets = useMemo(
    () => reportTickets.filter((ticket) => ticketUsesJira(config, ticket)),
    [config, reportTickets]
  );
  const currentWindowTickets = useMemo(() => getJiraInsightWindowTickets(tickets, 30), [tickets]);
  const previousWindowTickets = useMemo(() => getJiraInsightWindowTickets(tickets, 30, true), [tickets]);
  const resolvedTickets = tickets.filter(isTicketResolvedForInsights);
  const openTickets = tickets.filter(isTicketOpenForInsights);
  const slaBreaches = tickets.filter((ticket) => ticket.slaState === "breach");
  const avgResolutionHours = averageJiraInsightHours(tickets.map(getJiraInsightResolutionHours));
  const avgFirstResponseHours = averageJiraInsightHours(tickets.map(getTicketFirstResponseHours));
  const previousAvgResolutionHours = averageJiraInsightHours(previousWindowTickets.map(getJiraInsightResolutionHours));
  const previousSlaBreaches = previousWindowTickets.filter((ticket) => ticket.slaState === "breach").length;
  const highPriorityOpen = getJiraInsightHighPriorityTickets(openTickets).length;
  const reopenedTickets = tickets.filter((ticket) =>
    ticket.audit.some((entry) => entry.eventType.toLowerCase().includes("reopen"))
  ).length;
  const trendSeries = useMemo(() => buildJiraInsightTrendSeries(tickets), [tickets]);
  const statusBuckets = useMemo(
    () => buildJiraInsightBuckets(tickets, getJiraInsightStatusLabel, ["#3b82f6", "#60a5fa", "#22c55e", "#ef4444", "#f59e0b"]),
    [tickets]
  );
  const priorityBuckets = useMemo(
    () => buildJiraInsightBuckets(tickets, (ticket) => getReportValue(ticket.priority, "Unassigned priority"), ["#ef4444", "#f97316", "#eab308", "#22c55e", "#94a3b8"]),
    [tickets]
  );
  const slaBuckets = useMemo(
    () => [
      {
        label: "Within SLA",
        value: tickets.filter((ticket) => ticket.slaState !== "breach").length,
        percentage: tickets.length ? (tickets.filter((ticket) => ticket.slaState !== "breach").length / tickets.length) * 100 : 0,
        color: "#22c55e"
      },
      {
        label: "Breached",
        value: slaBreaches.length,
        percentage: tickets.length ? (slaBreaches.length / tickets.length) * 100 : 0,
        color: "#ef4444"
      }
    ],
    [slaBreaches.length, tickets]
  );
  const teamRows = useMemo(() => {
    const rows = buildJiraInsightBuckets(tickets, (ticket) => getReportValue(ticket.pru, "Unassigned team"));

    return rows.slice(0, 6).map((bucket) => {
      const teamTickets = tickets.filter((ticket) => getReportValue(ticket.pru, "Unassigned team") === bucket.label);
      const teamResolved = teamTickets.filter(isTicketResolvedForInsights);
      const teamOpen = teamTickets.length - teamResolved.length;
      const teamAvgResolution = averageJiraInsightHours(teamTickets.map(getJiraInsightResolutionHours));
      const teamWithinSla = teamTickets.filter((ticket) => ticket.slaState !== "breach").length;

      return {
        team: bucket.label,
        open: teamOpen,
        resolved: teamResolved.length,
        avgResolution: formatJiraInsightDuration(teamAvgResolution),
        sla: teamTickets.length ? `${Math.round((teamWithinSla / teamTickets.length) * 100)}%` : "0%"
      };
    });
  }, [tickets]);
  const assigneeRows = useMemo(() => {
    const rows = buildJiraInsightBuckets(tickets, getTicketResourceName);

    return rows.slice(0, 6).map((bucket) => {
      const assigneeTickets = tickets.filter((ticket) => getTicketResourceName(ticket) === bucket.label);
      const assigneeResolved = assigneeTickets.filter(isTicketResolvedForInsights);

      return {
        assignee: bucket.label,
        open: assigneeTickets.length - assigneeResolved.length,
        resolved: assigneeResolved.length,
        avgResolution: formatJiraInsightDuration(averageJiraInsightHours(assigneeTickets.map(getJiraInsightResolutionHours)))
      };
    });
  }, [tickets]);
  const projectBuckets = useMemo(
    () => buildJiraInsightBuckets(tickets, (ticket) => getReportValue(ticket.product, "Unassigned project")),
    [tickets]
  );
  const releaseRows = useMemo(() => getJiraInsightReleaseRows(tickets), [tickets]);
  const deliveredTickets = resolvedTickets.filter((ticket) => getReleasePlanVersion(ticket) !== releasePlanUnplannedLabel).length;
  const bugAfterRelease = resolvedTickets.filter((ticket) => isBugReportTicket(config, ticket)).length;
  const bugAfterReleaseRate = deliveredTickets ? Math.round((bugAfterRelease / deliveredTickets) * 1000) / 10 : 0;
  const syncRows = useMemo(
    () =>
      tickets.slice(0, 8).map((ticket) => {
        const followUpStatus = getTicketJiraFollowUpStatus(ticket);

        return {
          ticket: ticket.key,
          jira: ticket.relatedJiraKey ?? "Not linked",
          status: getJiraStatusDisplayName(ticket, followUpStatus),
          updated: formatDateTimeDisplay(ticket.jiraDraft.followUpUpdatedAt ?? ticket.updatedAt)
        };
      }),
    [tickets]
  );
  const insightTabs: Array<{ id: JiraInsightsView; label: string }> = [
    { id: "overview", label: "Overview" },
    { id: "sla", label: "SLA" },
    { id: "teams", label: "Teams" },
    { id: "releases", label: "Releases" },
    { id: "sync", label: "Sync Status" }
  ];

  return (
    <div className="jira-insights-report reports-tab-panel" role="tabpanel">
      <div className="jira-insights-header">
        <div>
          <h3>Jira insights</h3>
          <p>Ticket delivery, SLA, team, release, and Jira sync metrics from the local portal dataset.</p>
        </div>
        <span>Last 30 days</span>
      </div>
      <div className="jira-insights-tabs" role="tablist" aria-label="Jira insight views">
        {insightTabs.map((tab) => (
          <button
            aria-selected={activeView === tab.id}
            className={activeView === tab.id ? "is-active" : ""}
            key={tab.id}
            role="tab"
            type="button"
            onClick={() => setActiveView(tab.id)}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {activeView === "overview" ? (
        <>
          <div className="jira-insight-kpi-grid">
            <JiraInsightKpiCard label="Open tickets" value={openTickets.length} trend={`${getJiraInsightTrendValue(currentWindowTickets.filter(isTicketOpenForInsights).length, previousWindowTickets.filter(isTicketOpenForInsights).length)} vs last 30 days`} />
            <JiraInsightKpiCard label="Resolved" value={resolvedTickets.length} trend={`${getJiraInsightTrendValue(currentWindowTickets.filter(isTicketResolvedForInsights).length, previousWindowTickets.filter(isTicketResolvedForInsights).length)} vs last 30 days`} tone="success" />
            <JiraInsightKpiCard label="SLA breached" value={slaBreaches.length} trend={`${slaBreaches.length - previousSlaBreaches >= 0 ? "+" : ""}${slaBreaches.length - previousSlaBreaches} vs last 30 days`} tone="danger" />
            <JiraInsightKpiCard label="Avg local resolution" value={formatJiraInsightDuration(avgResolutionHours)} trend={`${formatJiraInsightDuration(Math.abs(avgResolutionHours - previousAvgResolutionHours))} change`} tone="warning" />
            <JiraInsightKpiCard label="Avg first response" value={formatJiraInsightDuration(avgFirstResponseHours)} trend="from first ticket comment" />
          </div>
          <div className="jira-insight-overview-grid">
            <JiraInsightTrendChart title="Created vs resolved" points={trendSeries} />
            <JiraInsightDonut title="Tickets by status" buckets={statusBuckets} totalLabel={`${formatCount(tickets.length)} total`} />
            <JiraInsightQuickList
              items={[
                { title: `${slaBreaches.length} SLA breaches`, detail: `${Math.max(0, slaBreaches.length - previousSlaBreaches)} more than previous 30 days`, tone: "danger" },
                { title: "Resolution time", detail: `${formatJiraInsightDuration(avgResolutionHours)} average local resolution`, tone: "success" },
                { title: "High priority open tickets", detail: `${highPriorityOpen} high or critical tickets are open`, tone: "warning" },
                { title: "Reopened tickets", detail: `${reopenedTickets} tickets were reopened`, tone: "danger" }
              ]}
            />
            <JiraInsightBarList title="Tickets by priority" buckets={priorityBuckets} />
            <JiraInsightDonut title="SLA compliance" buckets={slaBuckets} totalLabel={`${Math.round(slaBuckets[0]?.percentage ?? 0)}% within SLA`} />
          </div>
        </>
      ) : null}

      {activeView === "sla" ? (
        <div className="jira-insight-split-grid">
          <div className="jira-insight-kpi-grid compact">
            <JiraInsightKpiCard label="Within SLA" value={`${Math.round(slaBuckets[0]?.percentage ?? 0)}%`} trend={`${formatCount(slaBuckets[0]?.value ?? 0)} tickets`} tone="success" />
            <JiraInsightKpiCard label="Breached SLA" value={`${Math.round(slaBuckets[1]?.percentage ?? 0)}%`} trend={`${formatCount(slaBuckets[1]?.value ?? 0)} tickets`} tone="danger" />
          </div>
          <JiraInsightBarList title="SLA by project" buckets={projectBuckets.map((bucket) => ({ ...bucket, value: tickets.filter((ticket) => ticket.product === bucket.label && ticket.slaState !== "breach").length }))} percentMode />
          <JiraInsightBarList title="SLA by priority" buckets={priorityBuckets.map((bucket) => ({ ...bucket, value: tickets.filter((ticket) => ticket.priority === bucket.label && ticket.slaState !== "breach").length }))} percentMode />
        </div>
      ) : null}

      {activeView === "teams" ? (
        <div className="jira-insight-split-grid">
          <JiraInsightTable
            title="Team performance"
            columns={["Team", "Open", "Resolved", "Avg resolution", "SLA"]}
            rows={teamRows.map((row) => [row.team, row.open, row.resolved, row.avgResolution, row.sla])}
          />
          <JiraInsightTable
            title="Top assignees"
            columns={["Assignee", "Open", "Resolved", "Avg resolution"]}
            rows={assigneeRows.map((row) => [row.assignee, row.open, row.resolved, row.avgResolution])}
          />
        </div>
      ) : null}

      {activeView === "releases" ? (
        <div className="jira-insight-split-grid">
          <div className="jira-insight-kpi-grid compact">
            <JiraInsightKpiCard label="Releases" value={releaseRows.length} trend="planned fix versions" />
            <JiraInsightKpiCard label="Tickets delivered" value={deliveredTickets} trend="resolved with fix version" tone="success" />
            <JiraInsightKpiCard label="Bugs after release" value={bugAfterRelease} trend={`${bugAfterReleaseRate}% defect rate`} tone="warning" />
          </div>
          <JiraInsightBarList title="Tickets delivered per release" buckets={releaseRows} />
          <JiraInsightTrendChart title="Bug trend after release" points={trendSeries.map((point) => ({ ...point, created: Math.max(0, Math.round(point.created / 2)), resolved: Math.max(0, Math.round(point.resolved / 2)) }))} />
        </div>
      ) : null}

      {activeView === "sync" ? (
        <div className="jira-insight-split-grid">
          <div className="jira-insight-kpi-grid compact">
            <JiraInsightKpiCard label="Linked Jira issues" value={tickets.filter((ticket) => ticket.relatedJiraKey).length} trend="portal tickets with Jira key" />
            <JiraInsightKpiCard label="Ready to create" value={tickets.filter((ticket) => canCreateJiraForTicket(ticket, config)).length} trend="workflow gates complete" tone="warning" />
            <JiraInsightKpiCard label="In progress" value={tickets.filter((ticket) => getTicketJiraFollowUpStatus(ticket) === "in_progress").length} trend="active Jira development" />
          </div>
          <JiraInsightTable
            title="Recent sync status"
            columns={["Ticket", "Jira", "Status", "Updated"]}
            rows={syncRows.map((row) => [row.ticket, row.jira, row.status, row.updated])}
          />
        </div>
      ) : null}
    </div>
  );
}

function JiraInsightKpiCard({
  label,
  tone = "info",
  trend,
  value
}: {
  label: string;
  tone?: "info" | "success" | "warning" | "danger";
  trend: string;
  value: number | string;
}) {
  return (
    <article className={`jira-insight-kpi tone-${tone}`}>
      <span>{label}</span>
      <strong>{typeof value === "number" ? formatCount(value) : value}</strong>
      <small>{trend}</small>
    </article>
  );
}

function JiraInsightTrendChart({
  points,
  title
}: {
  points: Array<{ label: string; created: number; resolved: number }>;
  title: string;
}) {
  const maxValue = Math.max(...points.flatMap((point) => [point.created, point.resolved]), 1);
  const width = 420;
  const height = 170;
  const padding = 28;
  const xStep = points.length > 1 ? (width - padding * 2) / (points.length - 1) : 0;
  const getPoint = (value: number, index: number) => {
    const x = padding + index * xStep;
    const y = height - padding - (value / maxValue) * (height - padding * 2);

    return `${x},${y}`;
  };

  return (
    <article className="jira-insight-chart wide">
      <header>
        <h4>{title}</h4>
        <div className="jira-insight-legend">
          <span className="created">Created</span>
          <span className="resolved">Resolved</span>
        </div>
      </header>
      <svg aria-label={title} role="img" viewBox={`0 0 ${width} ${height}`}>
        <line className="axis" x1={padding} x2={width - padding} y1={height - padding} y2={height - padding} />
        <polyline className="created-line" points={points.map((point, index) => getPoint(point.created, index)).join(" ")} />
        <polyline className="resolved-line" points={points.map((point, index) => getPoint(point.resolved, index)).join(" ")} />
        {points.map((point, index) => {
          const [createdX, createdY] = getPoint(point.created, index).split(",").map(Number);
          const [resolvedX, resolvedY] = getPoint(point.resolved, index).split(",").map(Number);

          return (
            <g key={`${title}-${point.label}`}>
              <circle className="created-dot" cx={createdX} cy={createdY} r="4" />
              <circle className="resolved-dot" cx={resolvedX} cy={resolvedY} r="4" />
              <text x={createdX} y={height - 8}>{point.label}</text>
            </g>
          );
        })}
      </svg>
    </article>
  );
}

function JiraInsightDonut({
  buckets,
  title,
  totalLabel
}: {
  buckets: ReportBucket[];
  title: string;
  totalLabel: string;
}) {
  const total = buckets.reduce((sum, bucket) => sum + bucket.value, 0);

  return (
    <article className="jira-insight-chart">
      <header>
        <h4>{title}</h4>
      </header>
      <div className="jira-insight-donut-layout">
        <div className="jira-insight-donut" style={{ background: getReportPieGradient(buckets) }}>
          <strong>{total ? Math.round((buckets[0]?.value ?? 0) / total * 100) : 0}%</strong>
          <span>{totalLabel}</span>
        </div>
        <div className="jira-insight-donut-legend">
          {buckets.map((bucket) => (
            <div key={`${title}-${bucket.label}`}>
              <span style={{ backgroundColor: bucket.color }} />
              <strong>{bucket.label}</strong>
              <small>{formatCount(bucket.value)} ({Math.round(bucket.percentage)}%)</small>
            </div>
          ))}
        </div>
      </div>
    </article>
  );
}

function JiraInsightBarList({
  buckets,
  percentMode = false,
  title
}: {
  buckets: ReportBucket[];
  percentMode?: boolean;
  title: string;
}) {
  const maxValue = Math.max(...buckets.map((bucket) => bucket.value), 1);
  const total = buckets.reduce((sum, bucket) => sum + bucket.value, 0);

  return (
    <article className="jira-insight-chart">
      <header>
        <h4>{title}</h4>
      </header>
      <div className="jira-insight-bars">
        {buckets.length === 0 ? <p className="report-empty-chart">No matching tickets</p> : null}
        {buckets.map((bucket) => {
          const valueLabel = percentMode && total
            ? `${Math.round((bucket.value / total) * 100)}%`
            : `${formatCount(bucket.value)} (${Math.round(bucket.percentage)}%)`;

          return (
            <div className="jira-insight-bar-row" key={`${title}-${bucket.label}`}>
              <span>{bucket.label}</span>
              <div>
                <strong style={{ backgroundColor: bucket.color, width: `${(bucket.value / maxValue) * 100}%` }} />
              </div>
              <small>{valueLabel}</small>
            </div>
          );
        })}
      </div>
    </article>
  );
}

function JiraInsightQuickList({
  items
}: {
  items: Array<{ title: string; detail: string; tone: "success" | "warning" | "danger" }>;
}) {
  return (
    <article className="jira-insight-chart jira-insight-quick">
      <header>
        <h4>Quick insights</h4>
      </header>
      <div>
        {items.map((item) => (
          <section className={`tone-${item.tone}`} key={item.title}>
            <strong>{item.title}</strong>
            <span>{item.detail}</span>
          </section>
        ))}
      </div>
    </article>
  );
}

function JiraInsightTable({
  columns,
  rows,
  title
}: {
  columns: string[];
  rows: Array<Array<number | string>>;
  title: string;
}) {
  return (
    <article className="jira-insight-table-card">
      <header>
        <h4>{title}</h4>
      </header>
      <div className="jira-insight-table-scroll">
        <table>
          <thead>
            <tr>
              {columns.map((column) => (
                <th key={`${title}-${column}`}>{column}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.length === 0 ? (
              <tr>
                <td colSpan={columns.length}>No matching data</td>
              </tr>
            ) : null}
            {rows.map((row, rowIndex) => (
              <tr key={`${title}-${rowIndex}`}>
                {row.map((cell, cellIndex) => (
                  <td key={`${title}-${rowIndex}-${cellIndex}`}>{cell}</td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </article>
  );
}

